// src/hooks/UseWatchedFolders.js
import { useCallback, useEffect, useState } from 'react';
import {
  fetchWatchedFolders,
  createWatchedFolder,
  deleteWatchedFolder,
} from '../api/SettingsApi';

const STORAGE_KEY = 'watchservice.watchedFolders';

function saveLocal(folders) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(folders));
  } catch {}
}

function loadLocal() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

export function useWatchedFolders() {
  const [folders, setFolders] = useState(loadLocal());
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const refresh = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const server = await fetchWatchedFolders();
      const list = Array.isArray(server) ? server : [];
      setFolders(list);
      saveLocal(list);
    } catch (e) {
      // 서버 실패 시 로컬 유지
      setError(e);
      const local = loadLocal();
      setFolders(local);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    refresh();
  }, [refresh]);

  const addFolderByPath = useCallback(async (path, name) => {
    const p = String(path || '').trim();
    if (!p) return;

    const folderName =
      String(name || '').trim() ||
      p.split(/[/\\]/).filter(Boolean).pop() ||
      '폴더';

    setError(null);

    try {
      const created = await createWatchedFolder({ name: folderName, path: p });

      setFolders((prev) => {
        const next = [created, ...(prev || [])].filter(Boolean);
        saveLocal(next);
        return next;
      });
    } catch (e) {
      // 서버 실패 시 로컬로라도 추가
      setError(e);
      const localId = Date.now();
      const fallback = { id: localId, name: folderName, path: p };

      setFolders((prev) => {
        const next = [fallback, ...(prev || [])];
        saveLocal(next);
        return next;
      });
    }
  }, []);

  const promptAndAddFolder = useCallback(async () => {
    const path = window.prompt('감시할 폴더 경로를 입력하세요.\n예) C:\\Users\\me\\Desktop');
    if (!path) return;
    await addFolderByPath(path);
  }, [addFolderByPath]);

  const removeFolder = useCallback(async (id) => {
    if (id === undefined || id === null) return;

    setError(null);

    // optimistic
    let prevSnapshot = null;
    setFolders((prev) => {
      prevSnapshot = prev;
      const next = (prev || []).filter((f) => f.id !== id);
      saveLocal(next);
      return next;
    });

    try {
      await deleteWatchedFolder(id);
    } catch (e) {
      // rollback
      setError(e);
      const rollback = prevSnapshot ?? loadLocal();
      setFolders(rollback);
      saveLocal(rollback);
    }
  }, []);

  return {
    folders,
    loading,
    error,
    refresh,

    addFolderByPath,
    promptAndAddFolder,
    removeFolder,

    // 필요 시 외부에서 강제 수정
    setFolders,
  };
}
